
class Solution { public: bool sl(string& words, string s1, string s2, string s3) { bool founds1 = false, founds2 = false, founds3 = false; if (s1.find(words[0])!=string::npos) founds1 = true; else if (s2.find(words[0])!=string::npos) founds2 = true; else if(s3.find(words[0])!=string::npos) founds3 = true; for (int i = 1; i < words.size(); i++) { if (founds1 && s1.find(words[i])==string::npos) { founds1 = false; break; } if (founds2 && s2.find(words[i])==string::npos) { founds2 = false; break; } if (founds3 && s3.find(words[i])==string::npos) { founds3 = false; break; } } bool rv = founds1 ? founds1 : founds2 ? founds2 : founds3?founds3:false; return rv; } vector<string> findWords(vector<string>& words) { int n = words.size(); vector<string> ans; string s1 = "qwertyuiopQWERTYUIOP"; string s2 = "asdfghjklASDFGHJKL"; string s3 = "zxcvbnmZXCVBNM"; for (int i = 0; i < n; i++) { bool sameline = sl(words[i], s1, s2, s3); if (sameline == true) ans.push_back(words[i]); } return ans; } };
